//! JavaScript bindings for the Lineage engine.
//!
//! Every document operation crosses this boundary as bytes in, bytes out.
//! TypeScript never parses document XML. Each method here wraps one method of
//! [`api::Session`], where the logic and its tests live; the shapes that cross
//! are in [`dto`] (decision 0010).
//!
//! No `forbid(unsafe_code)` here: code generated by `#[wasm_bindgen]` uses `unsafe`.

pub mod api;
pub mod cache;
pub mod dto;

use wasm_bindgen::prelude::{JsError, wasm_bindgen};

/// The engine version, so the shell can check it loaded the build it expects.
#[wasm_bindgen(js_name = engineVersion)]
#[must_use]
pub fn engine_version() -> String {
    lineage::ENGINE_VERSION.to_owned()
}

/// Returns a copy of the bytes it was given. Proves that `Uint8Array` crosses the
/// boundary in both directions without being altered.
#[wasm_bindgen(js_name = echoBytes)]
#[must_use]
pub fn echo_bytes(bytes: &[u8]) -> Vec<u8> {
    bytes.to_vec()
}

/// A call's result: a JSON envelope and any bytes. Free it once read.
#[wasm_bindgen]
pub struct Reply(api::Reply);

#[wasm_bindgen]
impl Reply {
    /// `{"ok":true,"value":…}` or `{"ok":false,"error":…}`.
    #[must_use]
    pub fn json(&self) -> String {
        self.0.json.clone()
    }

    /// New bytes for the file the call acted on, once.
    #[wasm_bindgen(js_name = takeFile)]
    pub fn take_file(&mut self) -> Option<Vec<u8>> {
        self.0.file.take()
    }

    /// A new file's bytes, once.
    #[wasm_bindgen(js_name = takeNewFile)]
    pub fn take_new_file(&mut self) -> Option<Vec<u8>> {
        self.0.new_file.take()
    }

    /// New bytes for a tailored version "Update N versions" wrote, by node id.
    #[wasm_bindgen(js_name = takeVersionFile)]
    pub fn take_version_file(&mut self, node: &str) -> Option<Vec<u8>> {
        let at = self.0.files.iter().position(|(n, _)| n == node)?;
        Some(self.0.files.remove(at).1)
    }

    /// A blob to store, by the hash listed in the outcome.
    #[must_use]
    pub fn blob(&self, hash: &str) -> Option<Vec<u8>> {
        self.0
            .blobs
            .iter()
            .find(|b| b.hash.as_str() == hash)
            .map(|b| b.bytes.clone())
    }
}

/// One task pane's engine.
