#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn engine_version_matches_crate() {
        assert_eq!(engine_version(), env!("CARGO_PKG_VERSION"));
    }

    #[test]
    fn echo_bytes_round_trips() {
        let all_values: Vec<u8> = (0..=u8::MAX).collect();
        assert_eq!(echo_bytes(&all_values), all_values);
        assert!(echo_bytes(&[]).is_empty());
    }
}
